params.command:
$ErrorActionPreference='Stop'
$repo='fengie/mhw-mods'
$gh=(Get-Command gh.exe -ErrorAction Stop).Source
& $gh auth status
if($LASTEXITCODE -ne 0){throw 'gh auth unavailable'}
& $gh api --method PATCH "repos/$repo" -f delete_branch_on_merge=true | Out-Null
if($LASTEXITCODE -ne 0){throw 'failed to enable delete_branch_on_merge'}
$state=& $gh api "repos/$repo" --jq '.delete_branch_on_merge'
if($LASTEXITCODE -ne 0){throw 'failed to verify repository setting'}
[pscustomobject]@{delete_branch_on_merge=$state} | ConvertTo-Json -Compress
